{
  "entityType": "ModbusTcpDevices",
  "description": "Modbus TCP communication devices. Create devices first, then create their variables as ModbusTcpVariables.",
  "operations": [
    "get",
    "insert",
    "update",
    "delete"
  ],
  "restPath": "/API/Config/ModbusTcpDevices",
  "notes": [
    "Deleting a device also deletes all variables under it."
  ],
  "insertSchema": {
    "fields": {
      "enable": {
        "valueType": "boolean",
        "required": true
      },
      "name": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^[a-zA-Z0-9_]\u002B$"
        }
      },
      "ipAddress": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$"
        }
      },
      "secondaryIp": {
        "valueType": "string",
