      },
      "unitId": {
        "valueType": "integer",
        "required": true
      },
      "scanRate": {
        "valueType": "integer",
        "required": true
      },
      "template": {
        "valueType": "string",
        "required": true,
        "validation": {
          "pattern": "^$|[a-zA-Z0-9_]\u002B$",
          "allowEmpty": true
        }
      },
      "description": {
        "valueType": "string",
        "required": true
      },
      "allowScanningBlocks": {
        "valueType": "boolean",
        "required": true
      },
      "maxBlockSizeAllowed": {
        "valueType": "integer",
        "required": true
      },
      "allowJumpingRegisters": {
        "valueType": "boolean",
        "required": true
      },
      "timeout": {
        "valueType": "integer",
        "required": true
      },
      "byteSwap": {
        "valueType": "boolean",
        "required": true
      },
      "wordSwap": {
        "valueType": "boolean",
        "required": true
      },
      "doubleSwap": {
        "valueType": "boolean",
        "required": true
      },
      "verbose": {
        "valueType": "integer",
        "required": true
      },
      "simulation": {
        "description": "Simulation mode. When enabled the device does not open its real connection; its variables stay present and are read and written in memory like Local variables with Good quality, so the project can be exercised without hardware.",
        "valueType": "boolean",
        "required": false
      }
    }
